 void reset(){epoch++;eqIntent++;if(commitTask!=null)commitTask.cancel(false);eq=null;matrix=null;eqPending.clear();eqReplacement=null;eqEnabled=null;matrixPending.clear();pendingPanel=null;positions.clear();eqSending=matrixSending=matrixBlocked=refreshing=false;properties.clear();eqMessage="Connect to Stadium";matrixMessage="Connect to Stadium";changed();}
 void enter(int next){section=next;readNow();}void readNow(){if(!m.connected||refreshing)return;boolean readProperties=section==2&&(properties.isEmpty()||System.nanoTime()-lastProperties>3_000_000_000L);if(section==2&&!readProperties&&!matrixOpen)return;refreshing=true;int generation=m.generation;Session s=m.session;long token=epoch,intent=eqIntent;m.worker.execute(()->{try{GlobalEQ.State e=section==3&&!eqSending?s.eq.read():null;Matrix.State x=matrixOpen&&!matrixSending?s.matrix.read():null;Map<String,Object> props=readProperties?CommandCenter.properties(s):null;if(matrixOpen)s.matrix.channels(s.matrix.midi());m.ui.post(()->{if(generation!=m.generation||token!=epoch)return;if(e!=null&&!eqSending&&intent==eqIntent){eq=e;eqMessage="Global EQ · changes apply immediately";}if(x!=null&&!matrixSending){if(matrix!=null)for(int o=1;o<=3;o++)try{for(Matrix.Strip row:x.strips(o))for(int f=0;f<2;f++)if(!same(get(row.raw,Matrix.FIELD[f]),get(matrix.strip(o,row.id).raw,Matrix.FIELD[f])))positions.remove(Matrix.Engine.key(o,row.id,f));}catch(Exception ignored){}matrix=x;matrixMessage=ready()?(s.bridge!=null?"PedalBridge · USB Matrix mixer":"USB Matrix mixer"):x.linked!=0?"Outputs are linked; unlink them on Stadium for independent mixes":m.session!=null&&m.session.bridge!=null?"Connect Stadium to PedalBridge by USB":"Connect and confirm Stadium USB MIDI to enable controls";}if(props!=null){properties=props;m.stompProperties=props;lastProperties=System.nanoTime();}refreshing=false;changed();});}catch(Exception e){m.ui.post(()->{if(generation!=m.generation||token!=epoch)return;refreshing=false;if(section==3)eqMessage=e.getMessage();if(matrixOpen)matrixMessage=e.getMessage();changed();});}});}
 void poll(){if(!m.connected||m.destroyed||m.busy)return;m.ui.post(()->{if((section==2||section==3||matrixOpen)&&!refreshing&&!eqSending&&!matrixSending)readNow();});}
 boolean canOpenMatrix(){Session s=m.session;return Matrix.canOpen(m.connected&&s!=null,s!=null&&s.bridge!=null?s.bridge.matrix:null,usb.port!=null);}
