 boolean transportReady(){Session s=m.session;if(!m.connected||s==null||matrix==null||matrix.linked!=0)return false;if(s.bridge!=null)return s.bridge.matrix;return usb.bound(device());}
 String device(){try{return m.state==null?"":hash(s(get(m.state.product,"host","snum")).trim().getBytes("UTF-8"));}catch(Exception e){return "";}}
