 void eqChanges(int output,List<GlobalEQ.Change> changes){if(eq==null||!m.connected||m.busy)return;if(this.output!=output&&!eqPending.isEmpty())return;this.output=output;for(GlobalEQ.Change c:changes)eqPending.put(c.key(),c);eqIntent++;if(commitTask!=null)commitTask.cancel(false);m.ui.removeCallbacks(eqDrain);m.ui.postDelayed(eqDrain,40);changed();}
 final Runnable eqDrain=this::drainEQ;
 void eqReplace(int output,Object replacement,Boolean enabled){if(eq==null||eqSending||!eqPending.isEmpty()||m.busy)return;this.output=output;eqReplacement=replacement;eqEnabled=enabled;eqIntent++;if(commitTask!=null)commitTask.cancel(false);drainEQ();}
 void drainEQ(){if(eqSending||!m.connected||eq==null||eqPending.isEmpty()&&eqReplacement==null&&eqEnabled==null)return;eqSending=true;List<GlobalEQ.Change> changes=new ArrayList<>(eqPending.values());eqPending.clear();Object replacement=eqReplacement;Boolean enabled=eqEnabled;eqReplacement=null;eqEnabled=null;GlobalEQ.State before=eq;Session s=m.session;int out=output,g=m.generation;long token=epoch;m.worker.execute(()->{try{GlobalEQ.State next=s.eq.stage(before,out,changes,replacement,enabled);m.ui.post(()->{if(g!=m.generation||token!=epoch)return;eq=next;eqSending=false;eqMessage="Global EQ · live update sent";changed();if(!eqPending.isEmpty()||eqReplacement!=null||eqEnabled!=null)drainEQ();else scheduleCommit();});}catch(Exception e){m.ui.post(()->{if(g!=m.generation||token!=epoch)return;eqSending=false;eqPending.clear();eqReplacement=null;eqEnabled=null;eqMessage=e.getMessage();m.error.accept(e.getMessage()+"\nNothing was resent. Refresh before editing again.");changed();readNow();});}});}
 void scheduleCommit(){long token=epoch,intent=eqIntent;int g=m.generation;GlobalEQ.State expected=eq;Session s=m.session;commitTask=m.worker.schedule(()->{if(g!=m.generation||token!=epoch||intent!=eqIntent)return;try{long revision=s.eq.beginCommit(expected);confirmEQ(s,expected,revision,g,token,intent,System.nanoTime()+5_000_000_000L);}catch(Exception e){eqError(g,token,intent,e);}},150,TimeUnit.MILLISECONDS);}
 void confirmEQ(Session s,GlobalEQ.State expected,long revision,int g,long token,long intent,long deadline){if(g!=m.generation||token!=epoch||intent!=eqIntent)return;try{GlobalEQ.State after=s.eq.confirm(expected,revision);if(after!=null){m.ui.post(()->{if(g==m.generation&&token==epoch&&intent==eqIntent){eq=after;eqMessage="Global EQ · settings confirmed";changed();}});return;}if(System.nanoTime()>deadline)throw new java.io.IOException("EQ change was sent, but storage confirmation is incomplete. Check Stadium before editing again.");commitTask=m.worker.schedule(()->confirmEQ(s,expected,revision,g,token,intent,deadline),150,TimeUnit.MILLISECONDS);}catch(Exception e){eqError(g,token,intent,e);}}
 void eqError(int g,long token,long intent,Exception e){m.ui.post(()->{if(g==m.generation&&token==epoch&&intent==eqIntent){eqMessage=e.getMessage();m.error.accept(e.getMessage()+"\nNothing was resent.");changed();}});}
 GlobalEQ.State eqPreview(){try{if(eqPending.isEmpty()&&eqReplacement==null&&eqEnabled==null)return eq;return eq==null?null:GlobalEQ.applying(eq,output,new ArrayList<>(eqPending.values()),eqReplacement,eqEnabled);}catch(Exception e){return eq;}}
 void enqueueMatrix(int source,int field,int value){if(!ready()||m.busy)return;String key=Matrix.Engine.key(matrixOutput,source,field);if(field>=2&&(matrixSending||!matrixPending.isEmpty()))return;if(field<2)positions.put(key,value);matrixPending.put(key,new int[]{matrixOutput,source,field,value});m.ui.removeCallbacks(matrixDrain);m.ui.postDelayed(matrixDrain,field<2?35:0);changed();}
 final Runnable matrixDrain=this::drainMatrix;
 void drainMatrix(){if(matrixSending||matrixPending.isEmpty()||!ready())return;String key=matrixPending.keySet().iterator().next();int[] c=matrixPending.remove(key);Matrix.State expected=matrix;matrixSending=true;int g=m.generation;long token=epoch;Session s=m.session;m.worker.execute(()->{try{Matrix.State after=s.matrix.set(expected,c[0],c[1],c[2],c[3],sender(s,g,token));m.ui.post(()->{if(g!=m.generation||token!=epoch)return;matrix=after;matrixSending=false;matrixMessage="Matrix control confirmed";changed();drainNextMatrix();});}catch(Exception e){matrixError(g,token,e);}});}
 Matrix.Sender sender(Session session,int generation,long token){String identity=device();return (kind,out,source,field,value,channel)->{require(generation==m.generation&&token==epoch&&m.connected&&m.session==session&&!session.closed,"Stadium connection changed; no MIDI sent");if(session.bridge!=null)session.bridge.matrix(kind,out,source,field,value,channel);else usb.send(identity,kind,out,source,field,value,channel);};}
 void matrixError(int g,long token,Exception e){m.ui.post(()->{if(g!=m.generation||token!=epoch)return;matrixSending=false;matrixBlocked=true;pendingPanel=null;matrixPending.clear();positions.clear();matrixMessage=e.getMessage();m.error.accept(e.getMessage()+"\nNothing was retried. Refresh to review current settings.");changed();});}
 void matrixRefresh(){if(matrixSending)return;matrixBlocked=false;positions.clear();matrixPending.clear();readNow();}
 void clearSolos(){if(!transportReady()||matrixSending||m.busy)return;matrixSending=true;Matrix.State expected=matrix;int g=m.generation,out=matrixOutput;long token=epoch;Session s=m.session;m.worker.execute(()->{try{Matrix.State after=s.matrix.clear(expected,out,sender(s,g,token));m.ui.post(()->{if(g!=m.generation||token!=epoch)return;matrix=after;matrixSending=false;matrixBlocked=false;positions.clear();changed();drainNextMatrix();});}catch(Exception e){matrixError(g,token,e);}});}
 void drainNextMatrix(){if(pendingPanel!=null){int out=pendingPanel;boolean closing=pendingPanelClose;pendingPanel=null;panel(out,closing);}else drainMatrix();}
 void panel(int out,boolean closing){matrixOutput=out;m.preferences.edit().putInt("matrixLastOutput",out).apply();matrixPending.clear();positions.clear();if(!ready()||m.busy){changed();return;}if(matrixSending){pendingPanel=out;pendingPanelClose=closing;changed();return;}matrixSending=true;Session s=m.session;int g=m.generation;long token=epoch;m.worker.execute(()->{try{s.matrix.panel(out,closing,sender(s,g,token));Matrix.State after=s.matrix.read();m.ui.post(()->{if(g==m.generation&&token==epoch){matrix=after;matrixSending=false;changed();drainNextMatrix();}});}catch(Exception e){matrixError(g,token,e);}});}
